-- aud.append_changes: Ruling P2 as amended by CR-032 (risk R-014): an entry stamped more than 5 minutes after the database clock takes the database clock instead and one warning security event (aud.clock_ahead) is written per call, so a server clock running ahead cannot push the chain into the future. Otherwise unchanged from S1.07.
create or replace function aud.append_changes(p_entries jsonb)
returns integer
language plpgsql security definer
set search_path = pg_catalog, pg_temp
as $fn$
declare
    e jsonb;
    head_day date;
    head_at timestamptz;
    head_hash bytea;
    at timestamptz;
    offered timestamptz;
    db_now timestamptz;
    capped integer := 0;
    latest_offered timestamptz;
    hash bytea;
    written integer := 0;
begin
    if p_entries is null or jsonb_typeof(p_entries) <> 'array' then
        raise exception 'aud.append_changes expects a json array' using errcode = '22023';
    end if;

    perform pg_advisory_xact_lock(hashtext('aud.change_log.chain'));
    db_now := clock_timestamp();
    -- The head is the latest row; the latest anchored day bounds the search to its partition (index ix_change_log_occurred_at, CR-029).
    select max(a.day) into head_day from aud.chain_anchors a;
    if head_day is not null then
        select c.occurred_at, c.row_hash into head_at, head_hash from aud.change_log c
        where c.occurred_at >= (head_day::timestamp at time zone 'UTC') order by c.occurred_at desc limit 1;
    end if;
    if head_hash is null then
        head_hash := decode(repeat('00', 32), 'hex');
    end if;

    for e in select value from jsonb_array_elements(p_entries) loop
        offered := (e ->> 'occurred_at')::timestamptz;
        if offered is null then
            raise exception 'aud.append_changes: occurred_at is required' using errcode = '23502';
        end if;
        at := offered;
        if at > db_now + interval '5 minutes' then
            at := db_now;
            capped := capped + 1;
            latest_offered := greatest(latest_offered, offered);
        end if;
        if head_at is not null and at <= head_at then
            at := head_at + interval '1 microsecond';
        end if;

        hash := sha256(head_hash || convert_to(aud.change_canonical(
            (e ->> 'id')::uuid, at, (e ->> 'actor_user_id')::uuid, e ->> 'actor_kind', e ->> 'entity_type', (e ->> 'entity_id')::uuid,
            (e ->> 'company_id')::uuid, e ->> 'action', e -> 'changes', (e ->> 'subject_person_id')::uuid, (e ->> 'correlation_id')::uuid,
            (e ->> 'ip_address')::inet, e ->> 'source', at, (e ->> 'created_by')::uuid), 'UTF8'));

        insert into aud.change_log (id, occurred_at, actor_user_id, actor_kind, entity_type, entity_id, company_id, action, changes,
                                    subject_person_id, correlation_id, ip_address, prev_hash, row_hash, created_at, created_by, source)
        values ((e ->> 'id')::uuid, at, (e ->> 'actor_user_id')::uuid, e ->> 'actor_kind', e ->> 'entity_type', (e ->> 'entity_id')::uuid,
                (e ->> 'company_id')::uuid, e ->> 'action', e -> 'changes', (e ->> 'subject_person_id')::uuid, (e ->> 'correlation_id')::uuid,
                (e ->> 'ip_address')::inet, head_hash, hash, at, (e ->> 'created_by')::uuid, e ->> 'source');

        insert into aud.chain_anchors (day, last_hash, verified_at) values ((at at time zone 'UTC')::date, hash, null)
        on conflict (day) do update set last_hash = excluded.last_hash, verified_at = null;

        head_at := at;
        head_hash := hash;
        written := written + 1;
    end loop;

    if capped > 0 then
        insert into aud.security_events (id, occurred_at, event_type, actor, subject, severity, details, created_at, created_by)
        values (gen_random_uuid(), db_now, 'aud.clock_ahead', p_entries -> 0 ->> 'actor_user_id', 'aud.change_log', 'warning',
                jsonb_build_object('entries', capped, 'latest_offered', latest_offered, 'database_time', db_now),
                db_now, (p_entries -> 0 ->> 'created_by')::uuid);
    end if;

    return written;
end
